root = Path(__file__).resolve().parents[1]
index_path = root / "index.html"
twin_path = root / "twin-pregnancy.html"

if not index_path.exists():
    raise SystemExit("Safety check failed: index.html not found")

index = index_path.read_text(encoding="utf-8")
if "HNClinicOutput" not in index:
    raise SystemExit("Safety check failed: HNClinicOutput not found in current production index.html")
if "</body>" not in index.lower():
    raise SystemExit("Safety check failed: closing </body> not found")

payload = "".join(PAYLOAD_B64.split())
html = gzip.decompress(base64.b64decode(payload)).decode("utf-8")

required = [
    "Twin Pregnancy Module — v2.15.0",
    "INTERGROWTH-21st",
    "Hadlock",
    "function printPersianMultiReport",
    "HNClinicOutput",
]
missing = [x for x in required if x not in html]
if missing:
    raise SystemExit("Twin module validation failed: " + ", ".join(missing))

twin_path.write_text(html, encoding="utf-8")

pattern = re.compile(re.escape(MARKER_START) + r".*?" + re.escape(MARKER_END), re.S)
if pattern.search(index):
    index = pattern.sub(LAUNCHER, index)
else:
    pos = index.lower().rfind("</body>")
    index = index[:pos] + "\n" + LAUNCHER + "\n" + index[pos:]

if index.count("HN_TWIN_V215_START") != 1 or index.count("HN_TWIN_V215_END") != 1:
    raise SystemExit("Launcher validation failed")
if "HNClinicOutput" not in index:
    raise SystemExit("Safety check failed after patch")

index_path.write_text(index, encoding="utf-8")
print("Twin Pregnancy v2.15.0 installed safely")
print("index bytes:", index_path.stat().st_size)
print("twin bytes:", twin_path.stat().st_size)
